return {rwnpc01={id="rwnpc01",dsc="他是福来镖局的少主，一身劲装利落挺拔，为人大方豪爽，眼神明亮锐利，透着少年意气与护镖人的沉稳干练。",sex="男",age=16,looks=25,showequip={},withCorpse=0},rwnpc02={id="rwnpc02",dsc="他一身打满补丁的短衫，瘦得像根枯木，眼角挂着眵目糊，手里攥着半截木棍，眼神总往旁人腰间瞟。",sex="男",age=30,looks=13,showequip={},withCorpse=0},rwnpc03={id="rwnpc03",dsc="他穿件油腻腻的短打，脸上一道斜疤从眉骨划到下巴，头发乱糟糟倒梳着，眼里透着精明。",sex="男",age=30,looks=15,showequip={},withCorpse=0},rwnpc04={id="rwnpc04",dsc="此人满脸横肉挤得眼睛只剩一条缝，露着黝黑肚皮，腰间缠着破麻绳，嘴里叼着草梗骂骂咧咧。",sex="男",age=30,looks=12,showequip={},withCorpse=0},rwnpc05={id="rwnpc05",dsc="他一脸络腮胡，头戴破旧毡帽，身披露棉的棉袄，眼神凶狠且带着几分焦躁。",sex="男",age=23,looks=10,showequip={},withCorpse=0},rwnpc06={id="rwnpc06",dsc="此人瘦脸窄眼，颧骨高耸，裹着补丁摞补丁的棉衣，裤脚卷起赤脚沾泥，佝偻着身子。",sex="男",age=30,looks=16,showequip={},withCorpse=0},rwnpc07={id="rwnpc07",dsc="此人光头锃亮，穿件浆洗发黄的破僧袍，领口磨破露着脖颈，眉粗眼凶，脸上堆着假笑却难掩阴鸷。",sex="男",age=30,looks=15,showequip={},withCorpse=0},rwnpc08={id="rwnpc08",dsc="他僧袍沾满污渍且袒露左臂，臂上有不少疤痕，身手透着股伪善与狠辣。",sex="男",age=30,looks=17,showequip={},withCorpse=0},rwnpc09={id="rwnpc09",dsc="此人身着半旧的绸缎长衫，面容圆润带些精明，眼神闪烁不定，说话时总下意识搓手，透着几分谨慎与心虚。",sex="男",age=42,looks=20,showequip={},withCorpse=0},rwnpc10={id="rwnpc10",dsc="镖局的赵镖头，身材魁梧结实，脸上刻着风霜痕迹，神情沉稳肃穆，站姿挺拔如松，自带久经江湖的干练气场。",sex="男",age=48,looks=19,showequip={},withCorpse=0},rwnpc11={id="rwnpc11",dsc="此人身着灰扑扑的短打，身材精瘦，眼神锐利且带着决绝，眉宇间藏着一股狠劲，因为挨饿导致脚步有些虚浮。",sex="男",age=20,looks=24,showequip={},withCorpse=0},rwnpc12={id="rwnpc12",dsc="他目光灼灼，嘴角紧抿，身上虽布衣草鞋却气场紧绷，举手投足间带着几分孤注一掷的凌厉。",sex="男",age=20,looks=19,showequip={},withCorpse=0},rwnpc13={id="rwnpc13",dsc="他身着华贵锦袍，腰系玉饰，体态微胖，面色红润，眼神精明且带着几分傲慢，举手投足间透着财大气粗的气场。",sex="男",age=38,looks=21,showequip={},withCorpse=0},rwnpc14={id="rwnpc14",dsc="此人身材高大健壮，身着劲装，面容冷峻，眼神锐利如鹰，站姿笔挺，时刻保持戒备。",sex="男",age=34,looks=18,showequip={},withCorpse=0},rwnpc15={id="rwnpc15",dsc="他穿一身整洁的灰布长衫，头发梳得一丝不苟，面容谦和却眼神锐利，说话慢条斯理，举止得体。",sex="男",age=50,looks=18,showequip={},withCorpse=0},rwnpc16={id="rwnpc16",dsc="他皮肤黝黑粗糙，双手布满老茧，身材结实粗壮，脸上带着风霜，神情憨厚朴实，身上沾着水汽与泥污。",sex="男",age=28,looks=16,showequip={},withCorpse=0},rwnpc17={id="rwnpc17",dsc="他肩宽背厚，穿着打补丁的短褂，额头布满汗珠，眼神疲惫却透着韧劲，动作麻利不拖沓。",sex="男",age=26,looks=14,showequip={},withCorpse=0},rwnpc18={id="rwnpc18",dsc="此人眼神明亮，皮肤黝黑，穿着单薄的短衫，动作矫健灵活，脸上带着几分爽朗，说话声音洪亮。",sex="男",age=30,looks=17,showequip={},withCorpse=0},rwnpc19={id="rwnpc19",dsc="他腰背微驼，脸上刻着皱纹，双手青筋凸起，神情木讷寡言，干活时沉稳有力。",sex="男",age=35,looks=20,showequip={},withCorpse=0},rwnpc24={id="rwnpc24",dsc="他是新来的漕运官，身着官府常服，腰束玉带，面容威严，眼神锐利，眉宇间带着几分官威与傲慢，说话语气不容置疑。",sex="男",age=30,looks=20,showequip={},withCorpse=0},rwnpc25={id="rwnpc25",dsc="他是镖局的管事，身着整洁的青布长衫，面容干练，眼神精明且处事周全，说话条理清晰。",sex="男",age=44,looks=20,showequip={},withCorpse=0},rwnpc26={id="rwnpc26",dsc="此人一身制式短甲，身材挺拔，面容严肃，眼神锐利，站姿规整，时刻留意周遭动静。",sex="男",age=27,looks=18,showequip={},withCorpse=0},rwnpc27={id="rwnpc27",dsc="他身着藏青官袍，腰束玉带，面容端庄，眉宇间带着官威，神情沉稳持重，说话语气平和却自带不容置喙的分量。",sex="男",age=39,looks=22,showequip={},withCorpse=0},rwnpc28={id="rwnpc28",dsc="他身着一袭深蓝色短衫，肤色微褐，腰间挂着异域配饰，举止豪爽，言谈间像是带着海风的洒脱气息。",sex="男",age=30,looks=20,showequip={},withCorpse=0},rwnpc29={id="rwnpc29",dsc="此人身着的粗布短褂，双手布满老茧，指关节粗大，面容憨厚，是附近有名的木匠。",sex="男",age=35,looks=19,showequip={},withCorpse=0},rwnpc30={id="rwnpc30",dsc="他推着简易货摊，身着打补丁的短衣，脸上带笑，眼神机灵，说话口齿伶俐，时刻打量过往行人，透着生意人的活络劲儿。",sex="男",age=20,looks=20,showequip={},withCorpse=0},rwnpc31={id="rwnpc31",dsc="他衣衫褴褛不堪，面黄肌瘦，头发枯黄杂乱，身形佝偻，不知是从哪逃难来的。",sex="男",age=32,looks=16,showequip={},withCorpse=0},rwnpc32={id="rwnpc32",dsc="他身材壮实，眼里凶中带着戾气，说话粗声粗气，举止蛮横。",sex="男",age=30,looks=17,showequip={},withCorpse=0},rwnpc33={id="rwnpc33",dsc="他满脸横肉，眼神凶狠，嘴角挂着痞笑，站姿歪斜，浑身透着蛮横霸道的匪气。",sex="男",age=30,looks=15,showequip={},withCorpse=0},rwnpc34={id="rwnpc34",dsc="他穿着件带补丁的短衫，身材精瘦，眼神警惕，脚步轻捷，四处张望时透着几分贼眉鼠眼的机警。",sex="男",age=32,looks=17,showequip={},withCorpse=0},rwnpc35={id="rwnpc35",dsc="此人身材魁梧，身手矫健，身着厚实的旧棉袄，面容严肃，死死盯着粮仓方向，怀里抱着武器，随时准备动手。",sex="男",age=28,looks=18,showequip={},withCorpse=0},rwnpc36={id="rwnpc36",dsc="他一身玄色劲装罩着件虎皮，身材高大威猛，脸上一道疤痕格外显眼，眼神阴鸷气场强悍，自带慑人的威严。",sex="男",age=40,looks=14,showequip={},withCorpse=0},rwnpc37={id="rwnpc37",dsc="他身着绣纹官袍，腰束镶玉腰带，面容俊朗却眼神阴鸷，嘴角常挂着似笑非笑的弧度，言谈间绵里藏针，自带城府深沉的压迫感。",sex="男",age=35,looks=19,showequip={},withCorpse=0},rwnpc38={id="rwnpc38",dsc="此人魁梧健壮，一身耐磨短打，面容黝黑带些风霜，眼神沉稳锐利，站姿如松，动作干脆不拖沓，透着久经护镖的干练。",sex="男",age=36,looks=16,showequip={},withCorpse=0},rwnpc39={id="rwnpc39",dsc="他穿着件半旧绸缎长衫，留着山羊胡，眼神活络却藏着阴狠，手指常年拨弄算盘显得格外灵活，言谈间总绕着利益。",sex="男",age=40,looks=18,showequip={},withCorpse=0},rwnpc40={id="rwnpc40",dsc="他身着锦袍，腰系玉扣，体态微胖，面色红润，眼神精明且带着贪婪，说话时皮笑肉不笑，举手投足间透着财大气粗的傲慢与算计。",sex="男",age=36,looks=20,showequip={},withCorpse=0},rwnpc41={id="rwnpc41",dsc="他一身黑衣，脸上还罩着块黑布挡住面孔，辨不出样貌，举止十分可疑。",sex="男",age=35,looks=15,showequip={},withCorpse=0},bsnpc01={id="bsnpc01",dsc="他为人十分老实，少年时本打算考取功名，可惜家道中落，于是学着别人落草为寇，但因为十分老实被赶出了山寨，如今耕田过日子倒也自在。",sex="男",age=29,looks=16,showequip={},withCorpse=0},bsnpc02={id="bsnpc02",dsc="他昔年曾是一名刀客，后被仇人追杀身负重伤，为平安小镇的居民所救，后在此安家退隐江湖。",sex="男",age=45,looks=15,showequip={},withCorpse=0},bsnpc03={id="bsnpc03",dsc="她是平安小镇的居民，在家中排行第二，早年嫁给了一个江湖浪人，后夫君远走江湖再未归来。",sex="女",age=44,looks=18,showequip={},withCorpse=0},bsnpc04={id="bsnpc04",dsc="她身着破旧的粗布衣，身上挂着用线绳穿好的十多双大大小小的草鞋、布鞋。",sex="女",age=45,looks=18,showequip={},withCorpse=0},bsnpc05={id="bsnpc05",dsc="他一副书生模样，但手中却拿着一个沉重的流星锤，虽是有模有样的耍着，但因气力不足，下盘紊乱，常常将流星锤砸入四周的石板，引得周围人群纷纷避让。",sex="男",age=17,looks=20,showequip={},withCorpse=0},bsnpc06={id="bsnpc06",dsc="他是平安小镇中出了名的恶霸，仗着家中有人当官平日里作威作福。",sex="男",age=28,looks=18,showequip={},withCorpse=0},bsnpc07={id="bsnpc07",dsc="她刚刚搬到平安小镇，生得颇有几分姿色，故引得临街儿郎思慕不已，扯出一段“倚门回首，却把青梅嗅”的佳话。",sex="女",age=23,looks=20,showequip={},withCorpse=0},bsnpc08={id="bsnpc08",dsc="他梳着一个长长的小辫，手上拿着一把桃木短剑，面目严肃，颇有几分“大侠”的样子。",sex="男",age=11,looks=19,showequip={},withCorpse=0},bsnpc09={id="bsnpc09",dsc="他时常喝得酩酊大醉，听说多年前也曾是浪荡江湖的剑客，后来不知为何埋剑藏名隐居于平安小镇。",sex="男",age=45,looks=20,showequip={},withCorpse=0},bsnpc10={id="bsnpc10",dsc="他手中拿着几个铜板，正盯着前方的菜来饭馆，不时往前走两步，又退两步，看起来十分纠结。",sex="男",age=23,looks=17,showequip={},withCorpse=0},bsnpc11={id="bsnpc11",dsc="他是平安小镇的居民，身穿粗布长衣，手中拿着一个鸟笼。鸟笼里关着一只翠鸟，毛色翠兰，十分夺目。",sex="男",age=35,looks=16,showequip={},withCorpse=0},bsnpc12={id="bsnpc12",dsc="他自称是响当当的江湖大侠，身具传奇，懂得天下所有武功。他手中时常抱着剑，装成一副十分冷酷的样子。",sex="男",age=35,looks=18,showequip={},withCorpse=0},bsnpc13={id="bsnpc13",dsc="他佝偻着背，手上拿着一个拐杖，正坐在路旁歇息。",sex="男",age=65,looks=15,showequip={},withCorpse=0},bsnpc14={id="bsnpc14",dsc="她个头要比同龄孩童还要小巧些，走起路来摇摇晃晃，手中拿着一个冰糖葫芦，笑嘻嘻的望着你。",sex="女",age=10,looks=18,showequip={},withCorpse=0},bsnpc15={id="bsnpc15",dsc="她是平安小镇的居民，父母常年在外，由祖母一手带大，十分懂事。",sex="女",age=10,looks=18,showequip={},withCorpse=0},bsnpc16={id="bsnpc16",dsc="他是平安小镇的居民，手中拿着一个鸡腿，胸前的衣襟沾满了油渍。",sex="男",age=35,looks=18,showequip={},withCorpse=0},bsnpc17={id="bsnpc17",dsc="她年轻时曾是武林中公认的美人，英雄迟暮，美人自然也有这么一天，自隐居平安小镇后，她除了自怜自哀以外成了统领平安小镇三姑六婆一起八卦的核心之人。",sex="女",age=45,looks=21,showequip={},withCorpse=0},bsnpc18={id="bsnpc18",dsc="她是平安小镇的居民，听闻早年逃荒而来，她的青梅竹马则于半道饿死，致使其一生未嫁。",sex="女",age=56,looks=18,showequip={},withCorpse=0},bsnpc19={id="bsnpc19",dsc="他是村中顽童，父亲是个马商，故小名叫“马儿”，日子久了大家反而忘记了他原本的名字。他跨着一个竹马，正学着戏文的那些江湖豪杰“行侠仗义”。",sex="男",age=10,looks=17,showequip={},withCorpse=0},bsnpc20={id="bsnpc20",dsc="他是平安小镇的居民，有几分小聪明，去年做了点小生意赚了不少钱，在镇中出了名的怕老婆，常常被罚跪搓衣板。",sex="男",age=33,looks=19,showequip={},withCorpse=0},bsnpc21={id="bsnpc21",dsc="他是平安小镇的居民，本是个教书先生，据说年轻时曾经中过举人，但是真是假不得而知。",sex="男",age=55,looks=16,showequip={},withCorpse=0},bsnpc22={id="bsnpc22",dsc="他是一个马贩，常年在外奔波，不久前在去往西域时被沙匪所劫，幸得江湖中的侠客路过救了他一命。可惜他身受重伤，落下了病根，自此不宜远行。",sex="男",age=35,looks=17,showequip={},withCorpse=0},bsnpc23={id="bsnpc23",dsc="他手上拿着一把钉耙，听说自小就想成为游走江湖的大侠，可惜祖上代代务农，故其父不允其出门学艺。",sex="男",age=21,looks=19,showequip={},withCorpse=0},bsnpc24={id="bsnpc24",dsc="他是平安小镇的居民，曾是附近县里头的师爷，公正无私，协助官老爷处理了不少冤案。在镇中颇有几分声望，受到邻里的尊重。",sex="男",age=55,looks=17,showequip={},withCorpse=0},bsnpc25={id="bsnpc25",dsc="他是平安小镇的普通居民，平日里都在田间务农，虽然大字不识几个，却喜欢观摩镇中老者下棋，故而看上去略给人几分聪慧之感。",sex="男",age=24,looks=18,showequip={},withCorpse=0},bsnpc26={id="bsnpc26",dsc="她走起路来颇有几分“婀娜”之感，听闻早年流落风尘被一名侠客所救，如今在这平安小镇里安度余生。",sex="女",age=43,looks=18,showequip={},withCorpse=0},bsnpc27={id="bsnpc27",dsc="他是一个江湖侠客，身后背着一把极为沉重的巨剑，名为“战戈”。他脸上有一道疤痕，不知是从何而来，下巴处许久没有打理的胡渣让他看上去十分沧桑。",sex="男",age=45,looks=23,showequip={},withCorpse=0},bsnpc28={id="bsnpc28",dsc="他是平安小镇的居民，曾在武馆学艺多年，如今在镇中教习些拳脚。",sex="男",age=27,looks=16,showequip={},withCorpse=0},bsnpc29={id="bsnpc29",dsc="他穿着朴素，此时正在安排一些苦力搬运货物。",sex="男",age=35,looks=20,showequip={},withCorpse=0},bsnpc30={id="bsnpc30",dsc="他是马三德的独子，自幼顽皮，跟他父亲一样不喜欢读书，整日从私塾里逃出来胡闹，自称天下没人能够管住他。",sex="男",age=10,looks=20,showequip={},withCorpse=0},bsnpc31={id="bsnpc31",dsc="他本是穷苦人家出生，识不得几个大字，少年时跟随一个药商做学徒，十年后凭借运气发了家，积累了些小财，娶妻生子。自发妻去世后搬离了原本的村子，来到平安小镇居住。",sex="男",age=45,looks=17,showequip={},withCorpse=0},bsnpc32={id="bsnpc32",dsc="他是平安小镇的糖贩，家中养了无数蜜蜂，做出的糖极为甜蜜。他为人亲和，时常会把自己做的各色糖果赠予镇中孩童。",sex="男",age=32,looks=17,showequip={},withCorpse=0},bsnpc33={id="bsnpc33",dsc="他身着破烂衣衫，不知从何而来，一会儿声称自己是“八指神丐”，一会儿又说自己是苏乞儿之徒。他手中端着的一个缺口白碗，据说是祖传宝物。",sex="男",age=17,looks=20,showequip={},withCorpse=0},bsnpc34={id="bsnpc34",dsc="他祖上曾是名扬江湖的大侠，多年前偶然路过平安小镇，故在此安家，不涉江湖事多年。",sex="男",age=45,looks=19,showequip={},withCorpse=0},bsnpc35={id="bsnpc35",dsc="浑身黝黑的打铁匠。",sex="男",age=31,looks=18,showequip={},withCorpse=0},bsnpc36={id="bsnpc36",dsc="他穿了一身黑色劲装，眼神灵动，浑身充满了少年人才有的活力。",sex="男",age=23,looks=23,showequip={},withCorpse=0},bsnpc37={id="bsnpc37",dsc="他闲散于江湖，自嘲自己学武不专，所以号“半武”。在平安小镇隐居多年，少有人看到他出招练武，只当是个寻常人，但其内力似乎深不可测。",sex="男",age=45,looks=25,showequip={},withCorpse=0},bsnpc38={id="bsnpc38",dsc="早年靠车马发家，如今生意遍布大江南北。他身材清瘦，两眼微凹，腰间挂着一把老旧的长鞭，据说是年少时所用。",sex="男",age=45,looks=20,showequip={},withCorpse=0},bsnpc39={id="bsnpc39",dsc="他衣衫褴褛，踩着一双破洞的草鞋，饿的面黄肌瘦，不知从何处逃难过来。",sex="男",age=35,looks=17,showequip={},withCorpse=0},zxnpc01={id="zxnpc01",dsc="他穿着儒雅，曾经高中进士，如今在平安小镇里做教书先生。",sex="男",age=38,looks=20,showequip={},withCorpse=0},zxnpc02={id="zxnpc02",dsc="一个技艺娴熟，手法精湛的老手艺人。",sex="男",age=65,looks=17,showequip={},withCorpse=0}}00000000000000